16	impl FormatRule<MdInlineItemList> for FormatMdInlineItemList {
17	    type Context = MarkdownFormatContext;
18	    fn fmt(&self, node: &MdInlineItemList, f: &mut MarkdownFormatter) -> FormatResult<()> {
19	        if self.print_mode.is_auto_link_like() {
20	            return self.fmt_auto_link_like(node, f);
21	        } else if self.print_mode.is_normalize_words() {
22	            return self.fmt_normalize_words(node, f);
23	        } else if self.print_mode.is_all() {
24	            return self.fmt_trim_all(node, f);
25	        } else if self.print_mode.is_pristine() {
26	            return self.fmt_pristine(node, f);
27	        } else if self.print_mode.is_clean() {
28	            return self.fmt_clean(node, f);
29	        }
30	
31	        let mut joiner = f.join();
32	
33	        let mut seen_new_line = false;
34	        for (index, item) in node.iter().enumerate() {
35	            match item {
36	                AnyMdInline::MdTextual(text) => {
37	                    if text.is_empty_and_not_newline()? && seen_new_line {
38	                        let entry = format_with(|f| {
39	                            write!(
40	                                f,
41	                                [text.format().with_options(FormatMdTextualOptions {
42	                                    should_remove: true,
43	                                    trim_start: false,
44	                                    ..Default::default()
45	                                })]
46	                            )
47	                        });
48	                        joiner.entry(&entry);
49	                    } else if text.is_newline()? {
50	                        let entry = format_with(|f| {
51	                            write!(
52	                                f,
53	                                [
54	                                    text.format().with_options(FormatMdTextualOptions {
55	                                        should_remove: true,
56	                                        trim_start: false,
57	                                        ..Default::default()
58	                                    }),
59	                                    hard_line_break()
60	                                ]
61	                            )
62	                        });
63	                        seen_new_line = true;
64	                        joiner.entry(&entry);
65	                    } else {
66	                        joiner.entry(&text.format().with_options(FormatMdTextualOptions {
67	                            should_remove: false,
68	                            trim_start: self.print_mode.is_start() && index == 0,
69	                            ..Default::default()
70	                        }));
71	                    }
72	                }
73	
74	                AnyMdInline::MdHardLine(hard_line) => {
75	                    seen_new_line = true;
76	                    joiner.entry(&format_with(|f| {
77	                        write!(
78	                            f,
79	                            [hard_line
80	                                .format()
81	                                .with_options(FormatMdFormatHardLineOptions {
82	                                    print_mode: self.print_mode,
83	                                })]
84	                        )
85	                    }));
86	                }
87	                AnyMdInline::MdInlineItalic(italic) => {
88	                    joiner.entry(&italic.format().with_options(FormatMdInlineItalicOptions {
89	                        should_keep_fences: self.keep_fences_in_italics,
90	                    }));
91	                    seen_new_line = false;
92	                }
93	                _ => {
94	                    joiner.entry(&item.format());
95	                    seen_new_line = false;
96	                }
97	            }
98	        }
99	
100	        joiner.finish()
101	    }
102	}
