use biome_markdown_parser::parse_markdown;

fn run(label: &str, source: &str) {
    println!("===== {label} =====");
    let parse = parse_markdown(source);
    println!("--- CST ---\n{:#?}", parse.tree());
    let options = MdFormatOptions::default();
    let result =
        biome_formatter::format_node(&parse.syntax(), MdFormatLanguage::new(options), false)
            .unwrap();
    let output = result.print().unwrap();
    println!("--- Formatted ---\n{:?}\n", output.as_code());
}

fn main() {
    run("backtick+lang+trailing", "```js    \nconsole.log(1);\n```\n");
    run("tilde", "~~~python\ndef hello():\n    pass\n~~~\n");
    run("tilde-long", "~~~~~~~~~~~\n~~~python\ndef f():\n    pass\n~~~\n~~~~~~~~~~~\n");
    run("comma-info", "```rust,ignore\nfn main() {}\n```\n");
    run("multi-space-info", "```rust,  ignore   expect_diagnostics\nfn main() {}\n```\n");
    run("leading-space-info", "```   rust\nfn main() {}\n```\n");
}
