use crate::prelude::*;
use crate::shared::TextPrintMode;
use biome_formatter::write;
use biome_markdown_syntax::{MdCodeNameList, MdFencedCodeBlock, MdFencedCodeBlockFields};

/// The fence character used for all formatted output. Regardless of whether
/// the source used backtick (`` ``` ``) or tilde (`~~~`) delimiters, the
/// formatter always normalizes to backticks (CommonMark §4.5).
const FENCE_CHAR: char = '`';

#[derive(Debug, Clone, Default)]
pub(crate) struct FormatMdFencedCodeBlock;
impl FormatNodeRule<MdFencedCodeBlock> for FormatMdFencedCodeBlock {
    fn fmt_fields(&self, node: &MdFencedCodeBlock, f: &mut MarkdownFormatter) -> FormatResult<()> {
        let MdFencedCodeBlockFields {
            l_fence,
            r_fence,
            r_fence_indent,
            content,
            code_list,
            indent,
        } = node.as_fields();

        let l_fence = l_fence?;

        // Compute the minimum fence length needed (CommonMark §4.5).
        // The fence must be strictly longer than any backtick sequence in the
        // content, otherwise the inner sequence would be parsed as a closing
        // fence. E.g. if the content contains ``` (3 backticks), the outer
        // fence needs at least 4. Only backticks are counted here because the
        // output always uses backtick delimiters, even for tilde-fenced input.
        let max_inner = longest_fence_char_sequence(node, FENCE_CHAR);
        let fence_len = (max_inner + 1).max(3);
        let normalized_fence: String = std::iter::repeat_n(FENCE_CHAR, fence_len).collect();

        write!(
            f,
            [
                indent.format(),
                format_replaced(
                    &l_fence,
                    &text(&normalized_fence, l_fence.text_trimmed_range().start())
                ),
                format_with(|f| write_info_string(&code_list, f)),
                hard_line_break(),
                content
